"""Synchronized bare/equipped review for every directed dry cargo turn."""
from pathlib import Path
import json
HERE=Path(__file__).resolve().parent
packs={k:json.loads((HERE/f'{k}-manifest.json').read_text()) for k in ['bare','helmet']}
data={s['id']:{'durations':s['frameDurationsMs'],'bare':s['frameFiles'],'helmet':next(t['frameFiles'] for t in packs['helmet']['states'] if t['id']==s['id'])} for s in packs['bare']['states']}
html='''<!doctype html><meta charset="utf-8"><title>Bill carry-turn matrix</title><style>body{background:#152027;color:#e6eff1;font:16px system-ui;margin:20px}p{max-width:85ch;color:#bdd0d2}button,select{font:inherit;background:#29404a;color:white;padding:6px}.grid{display:flex;gap:12px;flex-wrap:wrap}.card{background:#22343e;padding:12px}canvas{display:block}label{margin-left:12px}</style><h1>Bill — complete dry carry-turn candidate matrix</h1><p>Quarter turns and half turns share approved loaded poses. Feet remain planted. Bare and helmet views play together for checking proportions, fit and materials. Staged candidate; game integration and full-family polish remain.</p><label>Turn <select id="turn"></select></label><button id="play">Pause</button><button id="step">Next pose</button><label>Height <select id="size"><option>148</option><option selected>82</option><option>54</option><option>27</option></select></label><label>Speed <select id="speed"><option value="1">1×</option><option value="0.5">0.5×</option></select></label><span id="status"> Loading…</span><div class="grid"><div class="card"><strong>Bare · dark station</strong><canvas id="bare" width="368" height="400"></canvas></div><div class="card"><strong>Helmet · light station</strong><canvas id="helmet" width="368" height="400"></canvas></div></div><script>
const clips=DATA;let time=0,last=performance.now(),playing=true,manual=0;const turn=document.querySelector('#turn');for(const key of Object.keys(clips)){let o=document.createElement('option');o.value=key;o.textContent=key;turn.append(o)}turn.onchange=()=>{time=0;manual=0};document.querySelector('#play').onclick=()=>{playing=!playing;document.querySelector('#play').textContent=playing?'Pause':'Play'};document.querySelector('#step').onclick=()=>{playing=false;manual=(manual+1)%clips[turn.value].durations.length;document.querySelector('#play').textContent='Play'};
Promise.all(Object.values(clips).map(async t=>{t.total=t.durations.reduce((a,b)=>a+b,0)+400;for(const kind of ['bare','helmet'])t[kind+'Images']=await Promise.all(t[kind].map(f=>new Promise((resolve,reject)=>{const im=new Image;im.onload=()=>resolve(im);im.onerror=reject;im.src=f+'?v=matrix-v1'})))})).then(()=>{function draw(now){if(playing)time+=(now-last)*Number(document.querySelector('#speed').value);last=now;const t=clips[turn.value];let i=manual,v=time%t.total;if(playing){i=0;while(i<t.durations.length-1&&v>=t.durations[i])v-=t.durations[i++]};const s=Number(document.querySelector('#size').value)/148;for(const kind of ['bare','helmet']){const ctx=document.querySelector('#'+kind).getContext('2d');ctx.fillStyle=kind==='bare'?'#22343e':'#dae1e0';ctx.fillRect(0,0,368,400);ctx.drawImage(t[kind+'Images'][i],184-128*s,350-224*s,256*s,256*s)}document.querySelector('#status').textContent=' All 24 clips loaded · pose '+(i+1)+'/'+t.durations.length;requestAnimationFrame(draw)}requestAnimationFrame(draw)}).catch(e=>document.querySelector('#status').textContent='Load failed '+e);</script>'''
html=html.replace('Staged candidate; game integration and full-family polish remain.','Installed in Bill’s runtime loader. Native frame/clock checks pass; visual acceptance and full-family polish remain.')
(HERE/'index.html').write_text(html.replace('DATA',json.dumps(data)),encoding='utf-8');print('Built synchronized 24-state turn matrix review')
